#!/bin/sh
# Generated by conjecture - do not edit. It is rewritten on every check.
#
# Finds the project's compiled classes (Maven, Gradle or IntelliJ
# output) and bundled jars; when there are no compiled classes, it
# compiles the sources itself. Then it compiles the adapter against
# that classpath and records the classpath for the run step.
set -eu

cp=""
have_classes=0
add() {
	if [ -z "$cp" ]; then cp="$1"; else cp="$cp:$1"; fi
}

for d in /src/target/classes /src/build/classes/java/main /src/out/production/classes; do
	if [ -d "$d" ] && [ -n "$(find "$d" -name '*.class' -print -quit)" ]; then
		add "$d"
		have_classes=1
	fi
done
for j in /src/target/dependency/*.jar /src/lib/*.jar /src/libs/*.jar; do
	if [ -f "$j" ]; then add "$j"; fi
done

mkdir -p /adapter/classes
if [ "$have_classes" = 0 ]; then
	root=/src
	if [ -d /src/src/main/java ]; then root=/src/src/main/java; fi
	find "$root" -name '*.java' -not -path '*/test/*' >/adapter/sources.txt
	if [ ! -s /adapter/sources.txt ]; then
		echo "conjecture adapter: no compiled classes and no .java sources found under /src" >&2
		exit 2
	fi
	if [ -n "$cp" ]; then
		javac -nowarn -cp "$cp" -d /adapter/classes @/adapter/sources.txt
	else
		javac -nowarn -d /adapter/classes @/adapter/sources.txt
	fi
fi

add /adapter/classes
javac -nowarn -cp "$cp" -d /adapter/classes /adapter/ConjectureAdapter.java
printf '%s' "$cp" >/adapter/classpath
